-- A code to join a room by (anyone who knows it, decision 77), in the friend-code format.
ALTER TABLE rooms ADD COLUMN code CHAR(8) NULL;
-- Rooms made before this get one too (a collision among 31^8 codes would fail the index below; rerun then).
UPDATE rooms SET code = CONCAT(SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + FLOOR(RAND() * 31), 1), SUBSTRING('23456789ABCDEFGHJKMNPQRSTUVWXYZ', 1 + FLOOR(RAND() * 31), 1));
ALTER TABLE rooms MODIFY code CHAR(8) NOT NULL;
CREATE UNIQUE INDEX idx_rooms_code ON rooms (code);
